def p(*xs): return ''.join(f'<p>{x}</p>' for x in xs)
def table(head,rows): return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{x}</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(title,text): return f'<aside class="callout"><strong>{title}</strong><p>{text}</p></aside>'
def code(text): return '<pre><code>'+escape(text)+'</code></pre>'
def math(text): return '<div class="math">'+escape(text)+'</div>'

def chapter(page,lang):
    t=lambda en,zh: zh if lang=='zh' else en
    rows=[]
    def add(ident,title,intro,body,refs=(),diagram=None): rows.append((ident,title,intro,body,refs,diagram))
    if page=='concepts':
        add('layers',t('Separate the layers','分清不同层次'),t('“AI” can name a field, a model, an application or a whole operating system around a task. Ask which one is being discussed.','“AI”可能指研究领域、模型、应用或任务运行系统。先确认讨论的是哪一层。'),table([t('Term','概念'),t('Meaning','含义'),t('Example / boundary','例子 / 边界')],[
            ('AI',t('Methods for perception, prediction, planning and action','用于感知、预测、规划和行动的方法'),t('Includes search, rules and learned models','包括搜索、规则及学习模型')),
            ('ML / DL',t('Learn parameters from data; DL uses layered neural networks','从数据学习参数；DL 使用多层神经网络'),t('A classifier need not generate text or use tools','分类器不一定生成文本或使用工具')),
            ('LLM',t('A large learned language model; often also processes other modalities','大型语言模型，也可能处理其他模态'),t('Produces outputs conditioned on its input','根据输入生成输出')),
            ('Agent',t('A system that chooses actions, observes results and continues toward a goal','选择动作、观察结果并继续达成目标的系统'),t('An LLM can be its decision component','LLM 可作为其中的决策组件')),
            ('Harness',t('The surrounding runtime that makes the loop operable','让循环能实际运行的外围运行时'),t('Context, tools, permissions, state, tracing and stopping','上下文、工具、权限、状态、追踪及停止')),
            ('ChatGPT / Codex',t('Products with models, interfaces and configured capabilities','包含模型、界面和配置能力的产品'),t('A product name is not a model architecture','产品名称不是模型架构')),
        ]),('d2l','runtimes'),'layers')
        add('learning',t('Know what changes when the system learns','明确“学习”改变了什么'),t('A neural model changes its parameters during training. A conversation can change the information supplied to inference without updating those parameters.','神经模型通过训练改变参数。对话可以改变推理输入的信息，而不必更新参数。'),p(t('Supervised learning uses input/target pairs. Self-supervised learning derives targets from the data itself, such as the next token. Unsupervised objectives discover structure without the same explicit target labels. Reinforcement learning optimizes behavior from reward signals across actions. These labels describe training objectives, not mutually exclusive products.','监督学习使用输入 / 目标对；自监督学习从数据本身产生目标，如下一个 token；无监督目标在没有同样明确标签的情况下发现结构；强化学习根据动作产生的奖励信号优化行为。这些分类描述训练目标，不是互斥的产品类别。'),t('If you attach a new design document, retrieve a paragraph or save a project note, the next response can improve because the system now has better evidence. That observation alone is not evidence of fine-tuning. Keep parameter learning, in-context adaptation and persistent application memory separate.','上传设计文档、检索段落或保存项目笔记后，下一次回答可能因为获得更好证据而改善。这不等于发生了微调。应区分参数学习、上下文内适应与应用层持久记忆。')),('pytorch',))
        add('choice',t('Choose the smallest useful system','选择足以解决问题的系统'),t('Autonomy adds a runtime problem as well as a modeling problem.','自主性既带来模型问题，也带来运行时问题。'),p(t('For a fixed conversion with clear rules, ordinary code may be sufficient. For one document explanation, a model response may suffice. For a question over changing documents, retrieval may help. For a repository fix that requires exploration and tests, an agent loop is useful. For repeated deployment or customer data access, add durable state and authorization to the runtime.','固定规则转换可能只需普通代码；解释一份文档可能只需一次模型回答；查询不断变化的文档可加入检索；需要探索和测试的代码修复适合 Agent 循环；涉及重复部署或客户数据访问时，运行时还需持久状态与授权。'),t('An effective first question is “What evidence marks this task complete?” A code patch, a cited table and a sent message have different completion conditions. A fluent final response is not proof that the underlying action happened.','一个有效的起点是“什么证据表明任务完成？”代码补丁、有出处的表格和已发送消息有不同完成条件。流畅的最终回答不能证明底层动作已发生。')),('architecture',))
    elif page=='llm':
        add('tokens',t('From text to a probability distribution','从文本到概率分布'),t('A token is an element of the model’s vocabulary, not necessarily a word or character.','Token 是模型词表中的元素，不一定等于单词或字符。'),p(t('A tokenizer maps input to token IDs. Embedding lookup maps each ID to a vector; position information distinguishes order. A decoder-style Transformer transforms these representations into logits for candidate next tokens. A softmax turns logits into a distribution. After a token is selected, it becomes part of the prefix for the next step.','分词器将输入映射为 token ID；嵌入查表将 ID 映射为向量，位置信息用于区分顺序。Decoder 风格的 Transformer 将表示转换成候选下一个 token 的 logits，softmax 得到概率分布；选出的 token 加入前缀，继续下一步。'),t('Tokens can span part of a word, whitespace or punctuation. Chinese, source code and mixed-language text have different tokenization patterns. Count with the actual tokenizer when a limit matters; character-count heuristics are only rough estimates.','Token 可以包含词的一部分、空白或标点。中文、源代码和混合语言的分词模式不同。需要精确控制限制时应使用实际分词器；字符数估计仅是粗略近似。'))+math('P(x₁…xₙ) = ∏ᵢ P(xᵢ | x₁…xᵢ₋₁)\nL(θ) = − Σᵢ log Pθ(xᵢ | x<ᵢ)'),('transformer','d2l'),'decoder')
        add('attention',t('What attention contributes','注意力机制做了什么'),t('Each position forms queries, keys and values from its current representation.','每个位置从当前表示计算 query、key 和 value。'),p(t('A query/key score determines how strongly one position reads values from other permitted positions. Causal masking prevents reading future tokens in an autoregressive decoder. Multiple heads learn different projections; feed-forward blocks, residual connections and normalization transform and stabilize representations through successive layers. An attention weight is not a reliable explanation of the entire model’s decision.','Query / key 分数决定某个位置读取其他允许位置的 value 的权重。自回归 decoder 的因果掩码禁止读取未来 token。多头使用不同投影，前馈块、残差连接和归一化在多层中变换并稳定表示。单个注意力权重不能可靠解释整个模型的决策。'))+math('Attention(Q,K,V) = softmax(QKᵀ / √dₖ + mask)V\nQ = XWQ, K = XWK, V = XWV')+note(t('Architecture scope','架构范围'),t('This is a teaching sketch of a decoder Transformer. The original 2017 paper describes an encoder–decoder model. Current systems can use different position encodings, attention variants, mixtures of experts and multimodal components.','这是 decoder Transformer 的教学示意。2017 年原论文描述 encoder–decoder 模型；当前系统可采用不同位置编码、注意力变体、混合专家及多模态组件。')),('transformer',))
        add('limits',t('Why plausibility and truth can diverge','为什么合理表达可能不真实'),t('A language probability is not a fact-verification procedure.','语言概率不等于事实核验过程。'),p(t('The model can generalize patterns, solve problems and combine evidence, yet still invent a citation, confuse a date or produce a subtly wrong program. A missing fact, ambiguous task, misleading context or weak verification can all cause failure. Correct grammar and confidence do not calibrate the probability that a claim is true.','模型可以泛化模式、解决问题并组合证据，但仍可能编造引文、混淆日期或生成细微错误的程序。缺失事实、任务歧义、误导上下文和验证不足都可能导致失败。语法正确和表达自信不能校准主张的真实性。'),t('Use external feedback appropriate to the claim: a source passage for a quotation, execution for a calculation, a regression for a behavior and a permission check for an action. Even a passed test only supports the tested property under the stated conditions.','应按主张选择外部反馈：引文核对原文，计算执行核验，行为使用回归检查，动作检查权限。通过测试也仅支持给定条件下被测属性。')),('rlhf','eval'))
    elif page=='training':
        add('optimization',t('Loss, gradients and generalization','损失、梯度与泛化'),t('Learning adjusts parameters to reduce an objective on examples; useful behavior must still transfer to new cases.','学习调整参数以降低示例上的目标函数，实用行为仍需迁移到新案例。'),p(t('A forward pass predicts an output. A loss compares that output to a target or objective. Backpropagation computes gradients through the network; an optimizer updates parameters using a batch of examples. The learning rate controls the update scale. Adam-like optimizers use additional state, so their updates are more elaborate than the simple gradient step below.','前向过程产生预测；损失将输出与目标比较；反向传播计算经过网络的梯度；优化器使用一批示例更新参数。学习率控制更新尺度。Adam 类优化器使用额外状态，更新比下方简单梯度步骤更复杂。'),t('Training loss measures fit to training examples. Development data supports model and hyperparameter choices; a held-out test assesses transfer after those choices are fixed. For a binary classifier, accuracy can hide class imbalance. For a language model, next-token loss alone does not measure source fidelity or tool-task success.','训练损失衡量对训练示例的拟合；开发集支持模型和超参数选择；选择固定后，留出测试评估迁移。二分类准确率可能掩盖类别不均衡；语言模型下一个 token 损失本身不能衡量来源忠实度或工具任务成功。'))+math('Simple gradient step: θₜ₊₁ = θₜ − η ∇θ Lbatch(θₜ)\nθ: learned parameters; η: learning rate'),('d2l','pytorch'))
        add('pipeline',t('Pretraining and post-training do different work','预训练与后训练承担不同任务'),t('An illustrative pipeline, not a disclosure of the internals of every commercial model.','这里介绍通用示意流程，不代表所有商业模型的内部实现。'),p(t('Pretraining learns broad representations and prediction patterns from large corpora. Supervised fine-tuning (SFT) uses demonstrations of desired behavior. Preference learning compares candidate outputs; an RLHF approach can fit a reward model and optimize a policy, while DPO optimizes a preference objective without that same explicit reward-model-plus-RL loop. These are families of methods; a provider may combine or replace them.','预训练从大规模语料学习表示和预测模式；监督微调 SFT 使用理想行为示范；偏好学习比较候选输出。RLHF 可训练奖励模型再优化策略；DPO 使用偏好目标，而不采用相同的显式奖励模型加 RL 循环。这些是方法族，提供方可以组合或替换它们。'),t('Better preference scores need not imply better factual accuracy, robust authorization or long-task completion. Define what behavior the training data rewards and what errors the evaluation still finds.','偏好分数改善不一定意味着事实准确率、授权可靠性或长任务完成率改善。要明确训练数据奖励的行为，以及评估仍发现哪些错误。')),('rlhf','dpo'),'training')
        add('adaptation',t('Choose data access or parameter adaptation','选择资料访问或参数适配'),t('The thing that needs to change should determine the mechanism.','需要改变的对象应决定使用的机制。'),table([t('Mechanism','机制'),t('Changes','改变什么'),t('Good first question','首先问什么')],[
            (t('Prompt / examples','提示 / 示例'),t('Input for this inference','此次推理的输入'),t('Can a clear task and a few examples fix it?','清楚的任务及少量示例能否解决？')),
            ('RAG',t('Evidence retrieved at run time','运行时检索的证据'),t('Are the required facts fresh, permissioned and findable?','所需事实是否新鲜、有权访问且可检索？')),
            (t('Fine-tuning','微调'),t('Model parameters or adapters','模型参数或适配器'),t('Is a repeated behavioral pattern failing on held-out cases?','是否在留出案例上反复出现某种行为问题？')),
            ('LoRA',t('A low-rank parameter update, typically with base weights frozen','通常冻结基础权重，训练低秩参数增量'),t('Can a smaller update learn the required behavior?','较小参数增量能否学习所需行为？')),
        ])+math('LoRA teaching notation: W′ = W + BA\nrank(BA) ≤ r; choose r much smaller than the full matrix dimensions')+p(t('Fine-tuning is not a dependable database update. A model can still misrecall an identifier or private record. For exact facts, supply the authoritative record and verify the answer.','微调不是可靠的数据库更新方式；模型仍可能错误记忆标识或私有记录。精确事实应提供权威记录并核验答案。')),('lora','rag'))
        add('data',t('Data quality and evaluation determine the useful scale','数据质量与评估决定有效规模'),t('Training loss, task quality and operational value are different measurements.','训练损失、任务质量和实际价值是不同测量。'),p(t('Deduplicate and version data; check provenance, licensing, privacy and contamination. Separate training, development and held-out evaluation before using examples to tune behavior. A model that memorizes answers to a test can look capable without transferring to new tasks.','应去重并为数据设版本，检查来源、许可、隐私和污染。用示例调优前区分训练集、开发集和留出评估集。记住测试答案的模型可能表现很好，却无法迁移到新任务。'),t('Historical scaling-law studies examine relationships among parameters, data and compute within specific experimental regimes. They help plan experiments; they do not guarantee that any larger model is better at your workload. Track failure categories and the smallest system meeting your acceptance threshold.','历史缩放规律研究在特定实验范围考察参数、数据与计算量关系，可帮助规划实验，但不保证更大的模型在你的任务上更好。应跟踪失败类型，并寻找满足验收阈值的最小系统。')),('scaling','chinchilla','pytorch'))
    elif page=='inference':
        add('execution',t('Prefill, decode and the KV cache','Prefill、Decode 与 KV cache'),t('Inference uses learned weights to compute an output for the current input.','推理使用已有权重，为当前输入计算输出。'),p(t('Prefill processes the supplied prefix. Decode repeatedly computes and selects the next token. A KV cache reuses earlier attention keys and values instead of recomputing them at every step. It consumes memory that grows with sequence length and architecture details. It is not a durable project memory or a record of verified facts.','Prefill 处理输入前缀；Decode 重复计算并选择下一个 token。KV cache 重用先前的注意力 key / value，避免每步重新计算，内存占用随序列长度及架构变化。它不是项目持久记忆，也不是已核验事实库。'),t('Time to first token and total completion time answer different questions. Measure your own workload, including retrieval and tools. Batching improves throughput but can change latency. Quantization reduces numerical precision and memory use; quality and speed effects depend on the hardware, kernels and task.','首 token 延迟与总完成时间回答不同问题；测量应包含实际检索和工具。批处理可提高吞吐，也可能影响延迟。量化降低数值精度和内存占用；质量及速度效果依赖硬件、算子与任务。')),('flash','reasoning'),'inference')
        add('sampling',t('Sampling changes the selection rule','采样改变的是选择规则'),t('Temperature and top-p shape the distribution; neither verifies a claim.','Temperature 和 top-p 调整分布，但都不核验主张。'),p(t('Temperature rescales logits before selection. A smaller value generally concentrates mass; top-p retains a set of candidates whose cumulative mass reaches a chosen threshold. Greedy selection picks a highest-scoring candidate. None of these makes a wrong high-probability answer true. Even low randomness does not promise bit-for-bit reproducibility across every service or hardware configuration.','Temperature 在选择前缩放 logits；较小值通常使概率集中。Top-p 保留累计概率达到阈值的一组候选；贪心选择最高分候选之一。这些方法都不会让高概率错误答案变成正确答案；较低随机性也不保证所有服务或硬件配置下逐比特复现。'),t('Supported controls differ by model and endpoint. Do not paste a sampling parameter from another model’s example without checking the current schema. For extraction, first fix the evidence and output contract; then evaluate decoding choices.','模型和端点支持的参数不同，不能未经检查就复制另一模型的采样参数。抽取任务应先明确证据与输出契约，再评估解码选项。'))+math('pᵢ(T) = exp(zᵢ / T) / Σⱼ exp(zⱼ / T), for T > 0'),('prompt',))
        add('reasoning',t('Reasoning budgets are a resource choice','推理预算是一项资源选择'),t('Training for reasoning and spending compute during inference are separate ideas.','针对推理能力训练与推理时增加计算量是两个不同概念。'),p(t('Some systems can allocate more inference computation before returning an answer. Other techniques generate candidates, run checks and select or repair a result. More compute can help a difficult task but costs time and may not repair missing evidence. A visible explanation or reasoning summary is not a complete execution trace or proof of internal causality.','某些系统可在返回答案前分配更多推理计算；其他方法生成多个候选，检查后选择或修复。增加计算量可帮助困难任务，但耗时，也不一定弥补缺失证据。可见解释或推理摘要不是完整执行追踪，也不能证明内部因果过程。'),t('Compare task success, p95 latency and cost per accepted result under a fixed dataset. Model names, exact budgets, available settings and pricing change; this atlas teaches the measurement method and links to current documentation rather than fixing a model leaderboard.','在固定数据集上比较任务成功率、p95 延迟和每个可接受结果成本。模型名称、预算、设置及价格会变化；本站介绍测量方法并链接当前文档，不固化模型排行榜。')),('reasoning','eval'))
    elif page=='prompting':
        add('contract',t('Make the requested result testable','让任务结果可以验收'),t('A useful prompt is a task specification whose missing details have consequences.','有效提示是一份任务规格；遗漏的信息会影响结果。'),p(t('Describe the goal, audience, authoritative inputs, desired output and material constraints. Add success criteria that can be checked outside the model. Give examples when format or domain conventions are ambiguous. Start concise; expand only where a failure or actual constraint justifies it.','描述目标、受众、权威输入、输出及重要约束，加入可在模型外检查的成功条件。格式或领域惯例有歧义时给出示例。先简洁，再针对真实约束或失败补充。'))+code(t('Task: Compare the two supplied protocol drafts.\nOutput: a table of changed requirements, with section references.\nPreserve: the distinction between normative text and commentary.\nCompletion: every change is supported by both drafts; label ambiguities.','任务：比较提供的两份协议草案。\n输出：需求变化表，附章节定位。\n保留：规范性文本与评注的区别。\n完成条件：每项变化能在两份草案中核对；标注歧义。')),('chat-prompt',),'prompt-contract')
        add('structured',t('Use an output contract and a separate validator','使用输出契约与独立验证器'),t('Valid JSON answers a syntax question, not every semantic question.','合法 JSON 回答语法问题，不回答所有语义问题。'),p(t('A schema can require fields, enum values and types. Your application still needs to check identifiers, source support, bounds and business rules. Handle refusals, incomplete outputs and API errors explicitly. If the task asks for a temperature from a report, a valid numeric field can still contain the wrong unit or a number invented by the model.','Schema 可约束字段、枚举和类型；应用仍需检查标识、出处、范围及业务规则，并显式处理拒绝、不完整输出和 API 错误。例如从报告抽取温度，合法数值字段仍可能包含错误单位或编造数值。'),t('Few-shot examples should cover edge behavior: missing evidence, conflicting values and an allowed “unknown.” Evaluate new cases instead of repeatedly patching a prompt to memorize the same small set.','Few-shot 示例应涵盖边界行为：证据缺失、数值冲突以及允许的“未知”。要评估新案例，避免不断修改提示来记住同一小批样例。')),('structured','function'))
        add('debug',t('Diagnose the failing layer before rewriting the prompt','修改提示前先定位失败层'),t('Many apparent prompting failures are data, retrieval, tool or validation failures.','很多看起来像提示的问题，实际来自数据、检索、工具或验证。'),table([t('Observation','观察'),t('Investigate first','优先调查')],[
            (t('Correct answer is absent from the supplied material','输入资料不包含正确答案'),t('Missing evidence, retrieval recall or task scope','证据缺失、检索召回或范围')),
            (t('Answer quotes a retired document','引用已废弃文档'),t('Version filters, source authority and context selection','版本过滤、来源权威性和上下文选择')),
            (t('Agent claims an edit but no diff exists','Agent 声称修改但没有 diff'),t('Tool availability, execution result and done condition','工具可用性、执行结果及完成条件')),
            (t('Well-formed object violates access rules','格式正确的对象违反访问规则'),t('Application authorization, not just generation instructions','应用授权，而不只是生成指令')),
        ]),('eval',))
    elif page=='context':
        add('state',t('Context, memory and weights are different storage','上下文、记忆和权重是不同存储'),t('A long conversation is not the same as unlimited working memory.','长对话不等于无限工作记忆。'),table([t('Store','存储'),t('Content','内容'),t('Failure to consider','需要考虑的失败')],[
            (t('Model weights','模型权重'),t('Learned parameters','已学习参数'),t('Stale or unreliable recall; not a precise document store','陈旧或不可靠回忆；不是精确文档库')),
            (t('Current context','当前上下文'),t('Instructions, selected messages and tool results','指令、所选消息及工具结果'),t('Overflow, irrelevant material or omitted evidence','超限、无关材料或遗漏证据')),
            (t('Application memory','应用记忆'),t('Saved notes or structured records','保存的笔记或结构化记录'),t('Wrong scope, stale conclusions or cross-user leakage','范围错误、结论过时或跨用户泄露')),
            (t('Workspace artifacts','工作区产物'),t('Files, patches, logs and checkpoints','文件、补丁、日志和检查点'),t('A summary disagrees with current files','摘要与当前文件不一致')),
        ])+p(t('Preserve decisions, unresolved questions, source locations and the current artifact revision when compacting. Mark what is observed versus inferred. A summary is lossy; re-open the source when precision matters. Treat instruction text, external evidence and tool observations as distinct inputs.','压缩上下文时保留决策、待解决问题、来源位置及产物版本，区分观察和推断。摘要有损，精度重要时应重新读取原文。应区分指令文本、外部证据及工具观察。')),('middle','architecture'),'context')
        add('retrieval',t('RAG is an evidence pipeline','RAG 是证据处理管线'),t('Retrieval determines what the generator has the chance to use.','检索决定生成器有机会使用什么证据。'),p(t('Ingest documents with versions and permissions, split meaningful chunks, index them, retrieve candidates, rerank or filter, and supply selected passages with provenance. Dense embeddings support semantic similarity; keyword and hybrid search help exact identifiers. Similarity is not truth or permission. Apply resource access checks before private passages enter the model context.','文档入库时保存版本及权限，按语义切块、建立索引、检索候选、重排或过滤，再把带来源的段落送入模型。Dense embedding 支持语义相似；关键词及混合检索有助于精确标识。相似度不等于真实或获准访问；私有段落进入上下文前应检查资源权限。'),t('Separate retrieval recall from grounded answer accuracy. First ask whether the necessary passage was found, then whether the answer faithfully used it. Test no-answer cases and conflicting revisions. RAG does not guarantee that the model uses the right passage or that an embedded instruction in a document is harmless.','应区分检索召回与有依据的回答准确率：先问是否找到所需段落，再问回答是否忠实使用它。测试无答案案例及冲突版本。RAG 不保证模型选对段落，也不保证文档中的指令无害。')),('rag','embedding','retrieval'),'rag')
        add('budget',t('Budget for the next useful observation','为下一项有用观察分配预算'),t('Allocate space for instructions, evidence, tool results and the output.','为指令、证据、工具结果及输出分配空间。'),p(t('Keep the exact acceptance condition and a small authoritative excerpt. Reference large files by stable locations; inspect selected regions rather than pasting every log. Reserve output and reasoning space according to the selected model’s actual accounting. Prompt caching may reduce repeated-prefix cost or latency; it is not application memory or a permission boundary.','保留精确验收条件和少量权威原文。大型文件使用稳定位置引用，检查相关区域而不是粘贴全部日志。按所选模型实际计量方式为输出和推理保留空间。提示缓存可能降低重复前缀成本或延迟；它不是应用记忆或权限边界。'),t('The context-budget exercise uses invented units to demonstrate selection. It does not tokenize text, estimate an OpenAI bill or model attention quality.','本站上下文预算练习使用虚构单位展示取舍，不进行实际分词、估算 OpenAI 费用或模拟注意力质量。')),('middle',))
    elif page=='agents':
        add('loop',t('Observe, choose, act, check','观察、选择、行动、检查'),t('An agent is best understood through its interaction with an environment.','理解 Agent，重点看它怎样与环境交互。'),p(t('A task provides a goal and constraints. The system observes a partial view, chooses an action, gets a tool result, updates its working state and decides whether to continue. The environment includes files, services, users or a simulated world. The underlying real state is usually not fully visible; plans must be revised when observations contradict assumptions.','任务提供目标及约束；系统观察局部信息、选择动作、获得工具结果、更新工作状态，再决定是否继续。环境可以包含文件、服务、用户或模拟世界。真实状态通常不能完全观察，发现与假设矛盾时应调整计划。'),t('An LLM may choose the next action, but the runtime decides which actions can execute. A fixed workflow prescribes the route; an agent chooses parts of the route from observations. Many useful systems combine deterministic stages with a model-driven decision inside one stage. “More autonomous” is not automatically “more reliable.”','LLM 可以选择下一个动作，但运行时决定哪些动作能执行。固定工作流规定路线；Agent 根据观察选择部分路线。实用系统常将确定性阶段与其中的模型决策组合。更自主不自动意味着更可靠。'))+math('Teaching model: aₜ = policy(observation history, goal)\nEnvironment: stateₜ₊₁ → observationₜ₊₁\nRuntime: validate(aₜ) before execution'),('react','running'),'agent-loop')
        add('planning',t('Plans are hypotheses about useful next steps','计划是关于下一步的假设'),t('Use observations to earn each extension of the plan.','用观察结果支持计划的每次延伸。'),p(t('For a code fix, first reproduce or inspect the claimed failure, locate the responsible behavior, change it, then verify the relevant property. A plan can identify dependencies and parallel work, but completion requires actual evidence. An action sequence that looks sensible may still be based on a wrong file, stale data or an unobserved side effect.','代码修复先复现或检查失败、定位行为、修改，再验证相关属性。计划可识别依赖及并行任务，但完成需要实际证据。看似合理的动作序列仍可能使用错误文件、过期数据或遗漏副作用。'),t('Multi-agent work helps when subtasks have clear inputs, independent outputs and a reconciliation procedure. It adds communication cost, duplicated context and conflicting edits. Start with one agent and deterministic checks; add delegation only when measured gains outweigh coordination cost.','多 Agent 在子任务输入清楚、输出独立且可合并时有帮助，但增加通信成本、上下文重复及修改冲突。先使用单 Agent 和确定性检查，再根据实际收益决定是否委派。')),('runtimes',))
        add('failure',t('Treat progress and termination as explicit states','把进展和终止作为显式状态'),t('An agent that cannot stop correctly is difficult to operate.','不能正确停止的 Agent 很难稳定运行。'),table([t('State / event','状态 / 事件'),t('Required behavior','所需行为')],[
            (t('Completed','完成'),t('The output satisfies the acceptance condition with evidence','输出满足验收条件并有证据')),
            (t('Blocked','受阻'),t('Name the missing input or permission; preserve a resumable checkpoint','明确缺失输入或权限，保存可恢复检查点')),
            (t('Tool timeout','工具超时'),t('Find out whether a side effect occurred before retrying','重试前确认是否已产生副作用')),
            (t('Repeated no progress','反复无进展'),t('Change the hypothesis or stop with a bounded failure report','改变假设，或停止并给出有限失败报告')),
            (t('Budget exhausted / cancelled','预算耗尽 / 取消'),t('Stop new work and return the current state and remaining work','停止新工作，返回当前状态及未完成项')),
        ])+p(t('A loop bound limits damage and cost; it does not prove correctness. An idempotency key can help a tool distinguish a replay from a new request. Repeatedly sending “continue” should not duplicate a payment, message or deployment.','循环上限限制损害和成本，不证明正确性。工具可通过幂等键区分重放和新请求；重复“继续”不应重复支付、发送消息或部署。')),('running','sandbox'))
    elif page=='harness':
        add('ownership',t('The runtime around the model','模型外围的运行时'),t('Harness is a broad engineering term; its exact responsibilities vary across implementations.','Harness 是宽泛工程术语，不同实现的职责范围可能不同。'),p(t('For this atlas, an agent harness assembles model input, exposes tool definitions, routes proposals, records observations and drives the next turn. It also connects termination, timeouts, state persistence and the application’s permission checks. A model weights file cannot perform these jobs by itself. A test harness, by contrast, drives cases and assertions; both meanings occur in engineering.','本站将 Agent Harness 指为组装模型输入、提供工具定义、路由建议、记录观察并推动下一轮的运行时，它还连接终止、超时、状态持久化及应用权限检查。模型权重文件本身不能完成这些工作。工程中的 test harness 则负责驱动测试案例和断言，两种含义都存在。'),t('Separate control from compute. The trusted application can own identity, tool policy and durable audit state, while a sandbox handles scoped files and commands. A container is an execution environment, not the whole harness and not a complete security boundary by default.','区分控制与计算。可信应用可管理身份、工具策略及持久审计状态，沙箱处理限定文件与命令。容器是执行环境，不是完整 Harness，默认也不是完整安全边界。')),('architecture','sandbox'),'harness-boundary')
        add('runtime',t('The loop is small; the contracts are the hard part','循环很小，契约是关键'),t('The following is provider-neutral pseudocode, not an OpenAI API recipe.','下例是与提供方无关的伪代码，不是 OpenAI API 调用配方。'),code('for turn in range(max_turns):\n    context = assemble(goal, trusted_rules, observations, checkpoint)\n    proposal = model_step(context, allowed_tool_schemas)\n    if proposal.is_final:\n        return verify_final(proposal, acceptance, observations)\n    call = validate_schema(proposal)\n    authorize(user, task_capability, call)\n    result = execute_with_timeout_and_idempotency(call)\n    observations.append(normalize(result))\n    persist_checkpoint(observations, workspace_revision)\nreturn stopped("turn_budget", checkpoint)')+p(t('Schema validation checks shape. Authorization checks the actor, resource and action. Execution reports success or failure. Verification checks the task property. Keep these decisions separate: a schema-valid request can be unauthorized, and an authorized successful tool call can still produce the wrong artifact.','Schema 验证检查结构；授权检查主体、资源及动作；执行报告成败；验证检查任务属性。要将决策分开：格式正确的请求可能未获授权，获准并成功的工具调用也可能生成错误产物。')),('function','structured','running'))
        add('durability',t('Resume from facts, not a hopeful summary','从事实恢复，而不是从乐观摘要恢复'),t('Durable sessions need artifact and side-effect accounting.','持久会话需要记录产物及副作用。'),p(t('A useful checkpoint records the task and constraints, last observed tool result, tool-call IDs, workspace revision, verified outputs, unresolved work and resource consumption. After reconnecting, inspect current artifacts and reconcile pending actions. Do not infer that an interrupted call failed merely because its response was lost.','有用的检查点记录任务与约束、最近工具结果、调用 ID、工作区版本、已验证产物、待完成工作及资源消耗。重连后检查实际产物并核对待定动作；不能因为响应丢失就认定中断调用失败。'),t('Retry transient failures with limits and backoff; do not blindly retry a deterministic schema error. Minimize tool results before returning them to context, but retain raw evidence where it can be inspected. Trace the tool path and observed effects without collecting private model reasoning or unnecessary secrets.','临时故障可有限重试并退避；确定性 schema 错误不应盲目重试。送回上下文前压缩工具结果，同时保存可检查的原始证据。追踪工具路径及可观察效果，无需收集模型私有推理或无关秘密。')),('trace','sandbox'))
        add('implementations',t('Choose who owns the orchestration','选择编排由谁负责'),t('OpenAI offers more than one route; terminology and lifecycle are not interchangeable.','OpenAI 提供多个路线，它们的术语与生命周期不能混用。'),table([t('Route','路线'),t('What you own','你负责什么'),t('When to explore it','何时考虑')],[
            ('Responses API',t('Your application loop and tool handlers','应用循环及工具处理器'),t('A small integration where explicit control matters','需要明确控制的小型集成')),
            ('Agents SDK',t('Application deployment, policy and persistence configuration','应用部署、策略及持久化配置'),t('Code-based orchestration with a reusable runner','使用可复用 runner 的代码编排')),
            ('Agents API',t('Application tools and environment choices','应用工具及环境选择'),t('An OpenAI-managed Codex harness and durable session service','OpenAI 托管 Codex Harness 和持久会话服务')),
            ('Codex App Server',t('Your client UI and integration with Codex events','客户端界面及 Codex 事件集成'),t('Embed the Codex operating experience in a product','将 Codex 工作体验集成到产品')),
        ])+note(t('Check before implementing','实现前核对'),t('This is a conceptual route map reviewed on 30 Sep 2026. Follow the selected runtime’s current quickstart and lifecycle; a session, response, sandbox and thread are distinct resources. The local lab does not use any of these APIs.','此概念路线复核于 2026 年 9 月 30 日。应跟随所选运行时当前入门及生命周期说明；session、response、sandbox 和 thread 是不同资源。本地练习不调用这些 API。')),('runtimes','app-server'))
    elif page=='tools':
        add('calling',t('The model proposes; the application executes','模型提出调用，应用负责执行'),t('Function calling is a contract between generated arguments and real code.','函数调用连接生成的参数与真实代码。'),p(t('Expose a narrow function with a useful name, input schema, output shape, side-effect description and error contract. The model may choose the function and arguments; your application validates them, checks permissions, performs the operation and returns an observation. Returning text that says “file saved” does not establish that a file exists.','提供名称明确、输入 schema、输出结构、副作用说明及错误契约清楚的窄功能。模型可选择函数及参数，应用验证、检查权限、执行操作并返回观察。返回“文件已保存”的文本不能证明文件存在。'),t('Prefer structured results with stable identifiers and explicit error types. Set timeouts and result-size limits. Separate lookup from update where it helps policy. For writes, use replay-safe semantics and report the actual revision or receipt rather than an optimistic success sentence.','优先使用含稳定标识及显式错误类型的结构化结果，设置超时及返回大小限制。为策略需要区分查询与更新；写入使用可安全重放的语义，报告真实版本或回执，不用乐观成功句代替。')),('function',),'tool-sequence')
        add('extensions',t('Tools, MCP and skills are complementary','工具、MCP 与 Skill 相互补充'),t('Do not treat an integration protocol as an intelligence or permission upgrade.','集成协议不自动提升智能或权限。'),table([t('Component','组件'),t('Role','职责'),t('What it does not guarantee','不保证什么')],[
            (t('Tool','工具'),t('A callable operation with inputs and results','可调用的输入 / 输出操作'),t('Correct arguments or authorized use','参数正确或获准使用')),
            ('MCP',t('A protocol connecting a host/client to servers that expose tools, resources and prompts','将 host / client 连接到提供工具、资源及提示的 server 的协议'),t('That every tool is trusted or allowed for every user','每个工具都可信、每位用户都有权限')),
            (t('Skill','Skill 技能'),t('Discoverable instructions and resources for a repeatable workflow','可发现的重复工作流指令及资源'),t('New OS privileges or deterministic compliance','新增 OS 权限或确定性遵守')),
            (t('Plugin / connector','插件 / 连接器'),t('Product packaging and service integration','产品封装及服务集成'),t('A consistent capability set across all products','所有产品中能力一致')),
        ])+p(t('A skill may describe how to combine tools or include helper scripts. Inspect its provenance and activation scope. Put stable repository facts in project instructions; put specialized reusable procedures in a skill; put one task’s request in the current prompt. Avoid copying every rule into all three places.','Skill 可描述怎样组合工具，也可包含辅助脚本。检查来源及触发范围。稳定仓库事实放项目指令，专门的重复过程放 Skill，本次任务放当前提示。避免在三处复制全部规则。')),('mcp','skills','agents-md'))
        add('policy',t('Authorization belongs at each resource boundary','每个资源边界都应检查授权'),t('A successful MCP login is not permission to read every object or perform every action.','MCP 登录成功不等于有权读取所有对象或执行所有动作。'),p(t('Check the authenticated user, selected task, tool scope and resource ACL where the action executes. A tool description is data from an integration, not a grant of authority. External documents may contain suggested commands; treat them as evidence to inspect within the task, not automatic permission to run them.','动作执行处检查已认证用户、当前任务、工具范围及资源 ACL。工具描述来自集成，是数据而不是授权。外部文档可能包含建议命令，应在任务范围内检查，而非自动获准执行。'),t('For a document search tool, test that user A cannot retrieve user B’s private passages before the generator sees them. For a write tool, test that retrying the same accepted operation does not duplicate the effect. Logs should identify decisions without embedding credentials.','文档搜索应测试 A 用户不能在生成器看到之前检索 B 用户私有段落；写工具应测试重试同一已接受操作不会重复效果；日志应记录决策而不嵌入凭据。')),('mcp-auth','sandbox-security'))
    elif page=='codex':
        add('surfaces',t('A coding task with a real workspace','带真实工作区的代码任务'),t('Use Codex to explore, edit, run checks and produce reviewable code changes.','使用 Codex 探索、编辑、执行检查并生成可审查的代码修改。'),p(t('Choose a surface by where the code and feedback live: the desktop app organizes projects and tasks, an IDE keeps nearby code visible, the CLI works from a repository, and cloud work uses a configured remote environment. Actual tools, network access and permissions depend on the surface and settings. Do not assume a task sees every file or uses the same environment as another task.','按代码和反馈位置选择入口：桌面应用组织项目与任务，IDE 保持邻近代码可见，CLI 从仓库运行，云任务使用配置好的远程环境。实际工具、网络和权限取决于入口及设置；不能假设某任务能看到所有文件，或与另一任务使用相同环境。'),t('Before a first change, establish the repository, relevant paths, working-tree state and a fast verification method. Give Codex a concrete behavior change and constraints. Review the resulting diff and observed checks, not only the explanation.','首次修改前明确仓库、相关路径、工作区状态及快速验证方法。给出具体行为变化及约束，检查最终 diff 和实际检查结果，而不仅看解释。')),('quickstart','projects'),'codex-loop')
        add('instructions',t('Make repository context small and durable','让仓库上下文简洁且持久'),t('AGENTS.md carries repository guidance; a skill carries a specialized workflow.','AGENTS.md 承载仓库指引；Skill 承载专门工作流。'),p(t('Codex discovers applicable instruction files according to its documented scope and precedence. Write durable facts: setup, architectural constraints, relevant checks and where generated files come from. Keep one-off requests out of global instructions. A nested directory can need its own guidance; inspect the current documentation when overrides matter.','Codex 按文档规定的范围和优先级发现适用指令文件。记录稳定事实：环境设置、架构约束、相关检查及生成文件来源。不要把一次性请求写入全局指令。子目录可能需要自身指引，涉及覆盖时查阅当前文档。'))+code(t('# Example repository guidance\nGenerated HTML comes from build.py; edit the source notes.\nRun python3 -B build.py after content changes.\nCheck local links and language pairs before completion.\nReport the changed pages and any unverified behavior.','# 仓库指引示例\nHTML 由 build.py 生成，应修改内容源文件。\n内容修改后运行 python3 -B build.py。\n完成前检查本地链接及语言对应页。\n报告修改页面及尚未核验的行为。'))+p(t('Keep skills short enough to discover and narrow enough to test. A “prepare release notes” skill should specify source inputs and reviewable output; it should not silently acquire publication credentials.','Skill 应简洁易发现、范围明确可测试。“整理发布说明”技能应指定输入与可审查输出，不应暗中获取发布凭据。')),('agents-md','skills'))
        add('workflow',t('One change, one visible acceptance condition','一次修改，对应一个可见验收条件'),t('Use a bounded patch task before a large autonomous refactor.','先练习有界补丁，再做大型自主重构。'),code(t('Fix the local invoice filter: tenant A must not see tenant B records.\nRead the implementation and the existing fixtures.\nPreserve the API and valid owner access.\nReproduce the failure, change the filter, and run the affected checks.\nFinish with the diff, observed results, and remaining limitations.','修复本地账单过滤：租户 A 不应看到租户 B 的记录。\n阅读实现和已有示例数据。\n保持 API 及合法所有者访问。\n复现失败、修改过滤逻辑并执行相关检查。\n完成时给出 diff、实际结果及剩余限制。'))+p(t('For longer tasks, keep a concise plan and checkpoint in the workspace. Separate independent changes with branches or worktrees when needed. Use the permission policy appropriate to the task; sandbox access and authorization to publish are distinct. A stopped or interrupted run needs its current state checked before continuing.','长任务在工作区保存简短计划及检查点；需要时用分支或 worktree 分开独立修改。按任务采用权限策略；沙箱访问权限与发布授权不同。暂停或中断后继续前，应核对实际状态。')),('chat-prompt','long-task','codex-sandbox'))
    elif page=='chatgpt':
        add('roles',t('Learn, compare and create reviewable artifacts','学习、比较并形成可审查产物'),t('ChatGPT is an application with model and tool capabilities, not merely the name of one LLM.','ChatGPT 是具备模型与工具能力的应用，不仅是某一个 LLM 的名称。'),p(t('Use a conversation for explanation, iterative questions and drafts. Use a project when related work needs shared source material and instructions. When available, a task-oriented Work surface can gather sources and create larger deliverables. File processing, search, connected apps and local execution depend on the account and selected surface; inspect what is actually enabled.','对话适合解释、反复提问及草稿；相关工作需要共享资料和指令时可使用项目。可用时，面向任务的 Work 入口可整理来源并创建较大产物。文件处理、搜索、连接应用及本地执行取决于账号和入口，应检查实际启用能力。'),t('ChatGPT can discuss code and Codex can explain concepts, so this is a workflow choice rather than a rigid capability split. Pick the surface that exposes the evidence needed for completion: source documents for research, or repository state and executable checks for a code change.','ChatGPT 也能讨论代码，Codex 也能解释概念；这里是工作方式选择，并非严格能力划分。按完成所需证据选择入口：研究需要来源文档，代码修改需要仓库状态及可执行检查。')),('quickstart','projects'),'chat-workflow')
        add('learning',t('Use an explanation–attempt–feedback loop','用“解释—尝试—反馈”学习'),t('The learner’s own attempt makes misunderstanding observable.','学习者自己的尝试，让误解变得可观察。'),code(t('Teach me causal attention using a three-token example.\nFirst define Q, K and V with a small diagram.\nThen give me one masking question and wait for my answer.\nAfter my attempt, explain the error and give a different case.\nEnd with what I should verify in the original paper.','用三个 token 的例子讲因果注意力。\n先用小图定义 Q、K、V。\n然后给一道掩码问题，等待我的答案。\n我尝试后解释错误，并换一个案例。\n最后列出应在原论文核对的内容。'))+p(t('Keep a study note with your attempted answer, correction and source passage. Ask for counterexamples and assumptions. For mathematics, work through a small calculation independently. For a tool workflow, reproduce it in a disposable local project. This is a study method; it does not depend on a specific named study-mode feature.','笔记保留自己尝试、纠正及原文位置；追问反例和假设。数学内容独立完成小计算，工具流程在可丢弃本地项目复现。这是一种学习方法，不依赖某个特定“学习模式”功能。')),('chat-prompt','d2l'))
        add('research',t('Keep facts, interpretations and decisions distinct','区分事实、解释与决定'),t('A polished research answer still needs evidence inspection.','精致的研究回答仍需要检查证据。'),p(t('Name the sources, time range and question. Ask for a table where every factual row has a source passage or direct link. Mark the model’s synthesis separately from reported facts. Open the underlying source for important claims and test whether it actually supports the sentence. A citation can exist and still be irrelevant.','明确来源、时间范围及问题；要求事实表中每行附原文位置或直接链接。将模型综合分析与来源报告的事实分开。重要主张打开底层来源，核对是否真正支持句子；引用存在也可能无关。'),t('For a decision memo, specify the acceptance criteria before the comparison: correctness, integration cost, data boundaries and operational burden. For sensitive inputs, use the organization’s allowed data route and verify current product controls; do not infer retention or training use from the presence of a chat interface.','决策备忘录在比较前明确验收标准：正确性、集成成本、数据边界及运维负担。敏感输入采用组织允许的数据路线并核对当前产品控制；不能从聊天界面推断保留或训练用途。')),('chat-prompt','eval'))
    elif page=='evaluation':
        add('contract',t('Evaluate the job you actually need done','评估真正需要完成的任务'),t('An evaluation harness turns acceptance criteria into repeatable observations.','评估 Harness 将验收条件转为可重复观察。'),p(t('Build representative cases with expected outcomes, evidence requirements and forbidden side effects. Include missing data, conflicting versions, malformed tool results, timeouts and unauthorized actions. Keep a held-out set that prompt tuning does not consume. Compare against a simple baseline, such as deterministic code or a single model response.','构建包含预期结果、证据要求及禁止副作用的代表案例，涵盖缺失数据、版本冲突、工具结果异常、超时及未获准动作。保留提示调优不使用的留出集，比较确定性代码或单次模型回答等简单基线。'),t('Unit tests assess a component. End-to-end evals assess the task outcome. Traces help locate where a run went wrong. Record the model/runtime version, prompt, dataset revision, tool configuration and environment. A benchmark score transfers only to the extent that its tasks and conditions resemble yours.','单元测试评估组件，端到端评估检查任务结果，追踪帮助定位失败环节。记录模型 / 运行时版本、提示、数据集版本、工具配置及环境。基准分数的可迁移程度取决于任务和条件与你的工作有多相似。')),('eval','gaia'),'evaluation')
        add('metrics',t('Quality, cost and risk need separate columns','质量、成本与风险需要分别记录'),t('Averages can hide a failure that matters more than the average success.','平均值可能掩盖比平均成功更重要的失败。'),table([t('Metric','指标'),t('Useful definition','实用定义'),t('Caution','注意事项')],[
            (t('Task success','任务成功'),t('Acceptance conditions satisfied / attempted cases','满足验收条件数 / 尝试案例数'),t('Publish the denominator and blocked cases','公布分母及阻塞案例')),
            (t('Grounding','证据支持'),t('Claims supported by the supplied authoritative evidence','主张有提供的权威证据支持'),t('Citations alone do not establish support','仅有引用不能证明支持')),
            (t('Unauthorized effects','未获准效果'),t('Observed resource or action boundary violations','观察到的资源或动作越界'),t('A hard constraint should not be averaged away','硬约束不能被平均掉')),
            (t('Latency / efficiency','延迟 / 效率'),t('p50 / p95, retries and cost per accepted task','p50 / p95、重试及每个可接受任务成本'),t('Include tools and failed runs','包含工具及失败运行')),
            (t('Operational recovery','运行恢复'),t('Completion or correct stop after injected failures','注入故障后完成或正确停止'),t('Check duplicated side effects after retry','检查重试后的重复副作用')),
        ]),('trace',))
        add('grading',t('Use judges carefully and keep objective checks','谨慎使用评审模型，保留客观检查'),t('An LLM judge can apply a rubric; it is another fallible component.','LLM 评审可应用评分准则，但本身也是可能出错的组件。'),p(t('Use executable assertions for objective properties where possible. For open-ended answers, define a rubric, blind system labels and calibrate a judge against expert-reviewed cases. Test sensitivity to answer length, ordering and persuasive wording. A model agreeing with another model is not independent evidence of factual correctness.','可客观判定的属性尽量使用可执行断言。开放回答定义评分准则、隐藏系统标签，并用专家核验案例校准评审。测试长度、顺序和说服性措辞的影响。两个模型一致不等于事实正确的独立证据。'),t('Repeat stochastic runs and report uncertainty. Tune on development cases; then run the held-out comparison once the candidates are fixed. Keep qualitative failure examples next to aggregate scores. The local evaluation exercise uses made-up fixed results to teach the denominator and policy tradeoff.','随机系统应重复运行并报告不确定性。在开发案例调优，候选固定后再比较留出集。汇总分数旁保留具体失败例。本站评估练习使用虚构固定结果，讲解分母与策略取舍。')),('eval','trace'))
    elif page=='security':
        add('boundaries',t('Treat instructions and outside content differently','区别对待指令与外部内容'),t('A retrieved passage can be useful evidence and still contain an unwanted instruction.','检索段落可以是有用证据，同时包含不应遵循的指令。'),p(t('Prompt injection exploits a system’s handling of untrusted content that attempts to steer behavior. The risk becomes concrete when a model can retrieve private data, call tools or influence another interpreter. Consider the path from source input through generated decisions to an observable effect, rather than counting suspicious strings alone.','提示注入利用系统对不可信内容的处理，尝试改变行为。当模型能检索私有数据、调用工具或影响另一解释器时，风险变得具体。要分析输入来源经生成决策到可观察效果的路径，而不只是统计可疑字符串。'),t('Keep task authority outside retrieved documents. Scope tools by user and resource; constrain destinations and arguments at the executor. Output filtering and model instructions can add defense, but do not replace access checks. An assistant saying “I ignored the instruction” is weaker evidence than a tool log showing the forbidden action was refused.','任务权限不应来自检索文档。按用户及资源约束工具，在执行器限制目的地及参数。输出过滤和模型指令可增加防御，但不替代访问检查。助手声称“忽略了指令”，弱于工具日志显示拒绝禁止动作的证据。')),('owasp','mcp-auth'),'security')
        add('system',t('The whole system has an attack surface','整个系统都有攻击面'),t('Model risks and application risks overlap but need different tests.','模型风险和应用风险会重叠，但需要不同测试。'),table([t('Surface','位置'),t('Failure to investigate','调查的失败'),t('Test / control','测试 / 控制')],[
            (t('Data / model supply chain','数据 / 模型供应链'),t('Poisoned examples, untrusted packages or changed checkpoints','污染示例、不可信包或权重版本变化'),t('Provenance, signed artifacts where available, held-out checks','来源、可用时的签名产物及留出检查')),
            (t('Memory / retrieval','记忆 / 检索'),t('Private cross-user context, stale or malicious records','跨用户私有上下文、过期或恶意记录'),t('Tenant-aware access checks, versioning and expiration','按租户访问检查、版本和到期机制')),
            (t('Tools / credentials','工具 / 凭据'),t('Broad authority exposed to generated code','生成代码获得过宽权限'),t('Narrow capabilities, external credential broker, audit','窄能力、外部凭据代理及审计')),
            (t('Generated output','生成输出'),t('Unsafe SQL, HTML or shell interpretation','不安全 SQL、HTML 或 shell 解释'),t('Parameterization, encoding and typed interfaces','参数化、编码及类型接口')),
            (t('Resource use','资源使用'),t('Runaway loops, huge outputs or repeated costly calls','失控循环、大量输出或重复高成本调用'),t('Turn/time/result limits and cancellation','轮数、时间、结果限制及取消')),
        ]),('aml','sandbox-security'))
        add('evidence',t('Test a denied action and a valid action','同时测试拒绝动作与合法动作'),t('A useful policy test establishes both enforcement and continued legitimate operation.','有效策略测试既证明限制有效，也证明合法操作仍可完成。'),p(t('In a synthetic tenant-A task, propose reading a tenant-B record and verify denial before its contents are returned. Then read the authorized tenant-A fixture and verify success. Inject a tool timeout and check that the run reports a bounded failure. Test duplicate write requests against a fake tool receipt; do not turn a training exercise into a production action.','在租户 A 示例任务中建议读取 B 记录，核验内容返回前被拒绝；然后读取合法 A 示例并核验成功。注入工具超时，检查运行报告有限失败。重复写请求使用模拟回执测试，不把教学练习变成生产动作。'),t('The harness trace exercise demonstrates runtime behavior with scripted proposals. It does not measure a real model’s resistance to prompt injection or make a claim that a particular product is secure.','本站 Harness 追踪练习使用脚本化建议展示运行时行为，不测量真实模型抵抗提示注入能力，也不宣称某产品安全。')),('owasp','trace'))
    elif page=='practice':
        add('route',t('Four passes through the subject','用四轮学习掌握主题'),t('Start from a task you can independently verify; the suggested time is flexible.','从可独立核验的任务开始，时间建议可调整。'),table([t('Pass','阶段'),t('Study','学习'),t('Deliverable','产出')],[
            (t('1 · Two evenings','1 · 两个晚上'),t('Concept map, LLM mechanics, training and inference','概念、LLM 原理、训练与推理'),t('Explain a token-to-output path and the limits of probability','解释 token 到输出的路径及概率的局限')),
            (t('2 · One week','2 · 一周'),t('Prompting, context and ChatGPT workflows','提示、上下文及 ChatGPT 工作流'),t('A cited comparison and a no-answer case','有出处的对照表及无答案案例')),
            (t('3 · One to two weeks','3 · 一到两周'),t('Agents, Harness, tools and Codex','Agent、Harness、工具与 Codex'),t('A small code patch with a reproduced failure and retest','包含复现与复测的小补丁')),
            (t('4 · One week','4 · 一周'),t('Evaluation, security and local labs','评估、安全与本地练习'),t('A task dataset, trace and accepted-result comparison','任务数据集、追踪及可接受结果比较')),
        ]),('d2l','quickstart'))
        add('projects',t('Three small projects with visible evidence','三个有可见证据的小项目'),t('Each project exercises a different layer without depending on all the others.','每个项目练习不同层，不要求串联全部方向。'),p(t('<strong>Document study in ChatGPT.</strong> Supply two public specification revisions. Ask for ten changed requirements with section references, plus two unchanged requirements as controls. Verify every row. Record unsupported and ambiguous claims rather than removing them from the denominator.','<strong>ChatGPT 文档学习。</strong>提供两份公开规范版本，整理十项变化及章节定位，加入两项未变化要求作对照；逐行核验，将无依据或模糊主张保留在分母中。'),t('<strong>Code repair in Codex.</strong> Use a disposable repository with a known filter bug. State the invariant, give fixtures and ask for the minimal relevant patch. Review the diff, run owner/non-owner checks and record a case outside the tested scope.','<strong>Codex 代码修复。</strong>在可丢弃仓库中使用已知过滤 bug，明确不变量及示例，要求最小相关补丁；检查 diff，运行所有者 / 非所有者检查，并记录测试范围外案例。'),t('<strong>Harness engineering.</strong> Run the downloaded scripted harness. Read the event stream, inspect authorization before execution, and change one timeout or step bound. Extend the validator and its tests together. Replace the fake planner with a model only after the runtime contract is understood.','<strong>Harness 工程。</strong>运行可下载脚本化 Harness，阅读事件流，检查执行前授权，修改一次超时或步数限制。一起扩展验证器与测试。理解运行时契约后再将模拟规划器换成模型。')),('chat-prompt','running'))
        add('notebook',t('Keep a reusable task and evaluation notebook','保留可复用任务及评估笔记'),t('A reproducible workflow needs more than a saved prompt.','可复现工作流不只需要保存提示。'),'<p class="download"><a href="labs/task-notebook.md" download>'+t('Download the bilingual task notebook ↓','下载双语任务笔记 ↓')+'</a></p>'+p(t('Record the task, source revisions, acceptance condition, configured capabilities, observed result, failures, cost/latency and retest. Keep the current product documentation link beside product-specific instructions. New model and runtime releases are reasons to rerun representative checks, not reasons to assume every old prompt is obsolete.','记录任务、来源版本、验收条件、配置能力、观察结果、失败、成本 / 延迟及复测。产品专用指令旁保留当前文档链接。模型与运行时更新应触发代表检查，不应直接假设旧提示全部失效。')),('eval',))
    return rows
